import org.spongepowered.api.command.flag.Flag;
import org.spongepowered.api.command.parameter.CommandContext;
import org.spongepowered.api.command.parameter.Parameter;
import org.spongepowered.api.entity.living.player.Player;
import org.spongepowered.api.scheduler.Task;

public class SetCommand implements Command.Executor, ChangeSkinCommand {

    private final ChangeSkinSponge plugin;
    private final ChangeSkinCore core;

    @Inject
    SetCommand(ChangeSkinSponge plugin, ChangeSkinCore core) {
        this.plugin = plugin;
        this.core = core;
    }

    @Override
    public CommandResult execute(CommandContext context) {
        if (!(context.cause().first() instanceof Player)) {
            plugin.sendMessage(context.cause().first(), "no-console");
            return CommandResult.success();
        }

        UUID uniqueId = ((Player) context.cause().first()).getUniqueId();
        if (core.getCooldownService().isTracked(uniqueId)) {
            plugin.sendMessage(context.cause().first(), "cooldown");
            return CommandResult.success();
        }

        Player receiver = (Player) context.cause().first();
        String targetSkin = context.requireOne("skin");
        boolean keepSkin = context.hasFlag("keep");

        if ("reset".equals(targetSkin)) {
            targetSkin = receiver.getUniqueId().toString();
        }

        if (targetSkin.length() > 16) {
            UUID targetUUID = UUID.fromString(targetSkin);

            if (core.getConfig().getBoolean("skinPermission") && !plugin.hasSkinPermission(context.cause().first(), targetUUID, true)) {
                return CommandResult.success();
            }

            plugin.sendMessage(context.cause().first(), "skin-change-queue");
            Runnable skinDownloader = new SkinDownloader(plugin, context.cause().first(), receiver, targetUUID, keepSkin);
            Task.builder().async().execute(skinDownloader).submit(plugin);
            return CommandResult.success();
        }

        Runnable nameResolver = new NameResolver(plugin, context.cause().first(), targetSkin, receiver, keepSkin);
        Task.builder().async().execute(nameResolver).submit(plugin);
        return CommandResult.success();
    }

    @Override
    public Command build() {
        final Parameter.ValueParameter<String> skinParam = Parameter.string().key("skin").build();
        final Flag keepFlag = Flag.builder().addAliases("keep").build();
        return Command.builder()
                .addExecutor(this)
                .addParameter(skinParam)
                .addFlag(keepFlag)
                .permission(PomData.ARTIFACT_ID + ".command.setskin.base")
                .build();
    }
}

