package com.github.games647.changeskin.sponge.bungee;

import com.github.games647.changeskin.core.message.SkinUpdateMessage;
import com.github.games647.changeskin.sponge.ChangeSkinSponge;
import com.github.games647.changeskin.sponge.task.SkinApplier;
import com.google.common.io.ByteArrayDataInput;
import com.google.common.io.ByteStreams;
import com.google.inject.Inject;

import java.util.Optional;

import org.spongepowered.api.Sponge;
import org.spongepowered.api.entity.living.player.Player;
import org.spongepowered.api.network.ChannelBinding;
import org.spongepowered.api.network.ChannelListener;
import org.spongepowered.api.network.side.Side;

public class UpdateSkinListener implements ChannelListener<ChannelBinding.RawChannel.DataEvent> {

    @Inject
    private ChangeSkinSponge plugin;

    @Override
    public void handlePayload(ChannelBinding.RawChannel.DataEvent data, Side side) {
        ByteArrayDataInput dataInput = ByteStreams.newDataInput(data.data().array());
        SkinUpdateMessage updateMessage = new SkinUpdateMessage();
        updateMessage.readFrom(dataInput);

        String playerName = updateMessage.getPlayerName();
        Optional<Player> receiver = Sponge.getServer().getPlayer(playerName);
        if (receiver.isPresent()) {
            Runnable skinUpdater = new SkinApplier(plugin, data.connection(), receiver.get(), null, false);
            Task.builder().execute(skinUpdater).submit(plugin);
        }
    }
}

